CREATE SCHEMA IF NOT EXISTS quality_postings_private; REVOKE ALL ON SCHEMA quality_postings_private FROM PUBLIC,anon; GRANT USAGE ON SCHEMA quality_postings_private TO authenticated,service_role; ALTER FUNCTION public.quality_posting_candidates(uuid) SET SCHEMA quality_postings_private; ALTER FUNCTION public.link_quality_posting(uuid,uuid,text) SET SCHEMA quality_postings_private;
CREATE FUNCTION public.quality_posting_candidates(p_id uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT quality_postings_private.quality_posting_candidates(p_id); $$;
CREATE FUNCTION public.link_quality_posting(p_id uuid,p_order_id uuid DEFAULT NULL,p_delivery_id text DEFAULT NULL) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT quality_postings_private.link_quality_posting(p_id,p_order_id,p_delivery_id); $$;
REVOKE ALL ON FUNCTION public.quality_posting_candidates(uuid),public.link_quality_posting(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_posting_candidates(uuid),public.link_quality_posting(uuid,uuid,text) TO authenticated; GRANT EXECUTE ON FUNCTION public.quality_posting_candidates(uuid) TO service_role;